INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7330806, 1144435, 179667, '<td valign="top">I like the tall buildings framing the shot.  I wish it was a little crisper/clearer?</td>', 'I like the tall buildings framing the shot.  I wish it was a little crisper/clearer?', '2015-03-20 00:18:44.000000', NULL, 1),
(7330807, 1144713, 30982, '<td valign="top">Ack!  His head has been replaced by the Madonna''s little finger!  His companion seems unconcerned.  Or perhaps just has not noticed yet.</td>', 'Ack!  His head has been replaced by the Madonna''s little finger!  His companion seems unconcerned.  Or perhaps just has not noticed yet.', '2015-03-20 00:18:49.000000', NULL, 1),
(7330808, 1144480, 179667, '<td valign="top">Fantastic tones.  Love the light.</td>', 'Fantastic tones.  Love the light.', '2015-03-20 00:19:01.000000', NULL, 1),
(7330809, 1144483, 30982, '<td valign="top">Ha!!  Joyful and fun.  Those faces!</td>', 'Ha!!  Joyful and fun.  Those faces!', '2015-03-20 00:19:07.000000', NULL, 1),
(7330810, 1144448, 30982, '<td valign="top">The disembodied finger is wonderful!!</td>', 'The disembodied finger is wonderful!!', '2015-03-20 00:19:25.000000', NULL, 1),
(7330811, 1144705, 179667, '<td valign="top">very busy!</td>', 'very busy!', '2015-03-20 00:19:39.000000', NULL, 1),
(7330812, 1144714, 179667, '<td valign="top">well seen</td>', 'well seen', '2015-03-20 00:19:53.000000', NULL, 1),
(7330813, 1144316, 179667, '<td valign="top">a fun collection</td>', 'a fun collection', '2015-03-20 00:20:18.000000', NULL, 1),
(7330814, 1144638, 179667, '<td valign="top">great tones!</td>', 'great tones!', '2015-03-20 00:20:31.000000', NULL, 1),
(7330815, 1144385, 30982, '<td valign="top">I swear I''ve seen him before.  Wonder if he wanders from town to town, or if I''ve seen him here before?  At any rate, I like your composition - the addition of the mural, and especially the cocooned drivers in their isolated cars, all staring forward.</td>', 'I swear I''ve seen him before.  Wonder if he wanders from town to town, or if I''ve seen him here before?  At any rate, I like your composition - the addition of the mural, and especially the cocooned drivers in their isolated cars, all staring forward.', '2015-03-20 00:20:51.000000', NULL, 1),
(7330816, 1144713, 179667, '<td valign="top">My eye''s not really sure what to focus on here so this is a bit hard to look at</td>', 'My eye''s not really sure what to focus on here so this is a bit hard to look at', '2015-03-20 00:22:27.000000', NULL, 1),
(7330818, 1144402, 179667, '<td valign="top">An interesting perspective</td>', 'An interesting perspective', '2015-03-20 00:23:37.000000', NULL, 1),
