(7332508, 1144448, 5822, '<td valign="top">I really like the interaction going on here, the man, the finger and the recording camera. Well seen.</td>', 'I really like the interaction going on here, the man, the finger and the recording camera. Well seen.', '2015-03-22 21:17:35.000000', NULL, 1),
(7332510, 1144716, 5822, '<td valign="top">I like the repeated theme and the wide angle distortion to emphasize it. Her gaze make it even more interesting.</td>', 'I like the repeated theme and the wide angle distortion to emphasize it. Her gaze make it even more interesting.', '2015-03-22 21:20:44.000000', NULL, 1),
(7332512, 1144435, 5822, '<td valign="top">could use a bit of contrast, imo, but I like the composition and POV.</td>', 'could use a bit of contrast, imo, but I like the composition and POV.', '2015-03-22 21:30:50.000000', NULL, 1),
(7332517, 1144232, 5822, '<td valign="top">An anguished time, for sure, and timely moment caught well.</td>', 'An anguished time, for sure, and timely moment caught well.', '2015-03-22 21:36:01.000000', NULL, 1),
(7332520, 1144483, 5822, '<td valign="top">amusing. I like the mother''s reaction.</td>', 'amusing. I like the mother''s reaction.', '2015-03-22 21:38:57.000000', NULL, 1),
(7332522, 1144656, 5822, '<td valign="top">I like the rhythm here.</td>', 'I like the rhythm here.', '2015-03-22 21:54:02.000000', NULL, 1),
